const SESSION_USER = 'alice'; // the authenticated chat user in this demo
const to = String(input.to || '').trim().toLowerCase();
// Egress allowlist: the agent cannot email outside the organisation.
if (!/^[^@\s]+@company\.local$/.test(to)) return `DENIED: external recipient ${to} is not allowed.`;
if (String(input.body || '').length > 1000) return 'DENIED: message body too long.';
return `EMAIL_SENT to=${to} subject=${input.subject || ''} body_chars=${String(input.body || '').length}`;

// Layer 1: cheap input filter for well-known injection phrasing.
// It is intentionally simple: it catches obvious attempts and logs them,
// while the tool-level controls below remain the real security boundary.
const patterns = [
  /ignore\s+(all\s+|any\s+)?(previous|prior|above)\s+instructions/i,
  /(reveal|print|show|repeat)\s+(your\s+)?(full\s+)?(system\s+prompt|instructions)/i,
  /you\s+are\s+now\s+/i,
  /developer\s+mode|jailbreak|DAN\b/i,
];
return $input.all().map(item => {
  const text = String(item.json.chatInput || '');
  const hit = patterns.find(p => p.test(text));
  return { json: { ...item.json, blocked: Boolean(hit), matched_rule: hit ? String(hit) : null } };
});
